insert into public.curated_courses (id, slug, title, description)
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('b313a3da-cc36-4cdf-88c4-3954b46e5331', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', null, 'topic'::public.curated_course_node_type, 'Foodservice Systems and Management Foundations', 'This section establishes the systems perspective used throughout the course. Students learn to see a food and nutrition operation as an interconnected set of people, resources, processes, controls, and outcomes rather than as a collection of isolated tasks.', 0),
  ('068318d7-bfc8-40e2-9e06-60f5013a3420', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'b313a3da-cc36-4cdf-88c4-3954b46e5331', 'subtopic'::public.curated_course_node_type, 'The foodservice systems model', 'The systems model helps managers trace how inputs are transformed and how feedback improves performance.', 0),
  ('a3536e88-2366-44f1-bc12-d8da64582f06', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '068318d7-bfc8-40e2-9e06-60f5013a3420', 'concept'::public.curated_course_node_type, 'Inputs: human, material, financial, facility, information, and time resources', null, 0),
  ('69608f74-320e-4969-8c1d-d7414b1ea315', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '068318d7-bfc8-40e2-9e06-60f5013a3420', 'concept'::public.curated_course_node_type, 'Transformation: procurement, production, distribution, service, and management processes', null, 1),
  ('63edd13e-0f57-4dcb-8714-8cdd1785548b', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '068318d7-bfc8-40e2-9e06-60f5013a3420', 'concept'::public.curated_course_node_type, 'Outputs: safe meals, nutrition outcomes, satisfaction, workforce outcomes, financial results, and waste', null, 2),
  ('8154597a-e9f7-49f3-914b-1d2da6d37815', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '068318d7-bfc8-40e2-9e06-60f5013a3420', 'concept'::public.curated_course_node_type, 'Control, feedback, boundaries, interfaces, and environmental forces', null, 3),
  ('a9e4bdc4-42aa-46ac-8005-8a87bcd4acb0', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'b313a3da-cc36-4cdf-88c4-3954b46e5331', 'subtopic'::public.curated_course_node_type, 'Management functions and organizational theory', 'Students use management theory to make intentional choices about planning, organizing, leading, staffing, and controlling.', 1),
  ('0e501e10-5a15-4cfe-849b-8ec1354720d6', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'a9e4bdc4-42aa-46ac-8005-8a87bcd4acb0', 'concept'::public.curated_course_node_type, 'Classical, human-relations, systems, contingency, and learning-organization perspectives', null, 0),
  ('004d5467-a5be-4eff-a4bd-68fb70f15ec5', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'a9e4bdc4-42aa-46ac-8005-8a87bcd4acb0', 'concept'::public.curated_course_node_type, 'Mission, vision, values, goals, objectives, policies, procedures, and standards', null, 1),
  ('ac1239c5-0e7f-49e0-a795-12b300bf46f6', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'a9e4bdc4-42aa-46ac-8005-8a87bcd4acb0', 'concept'::public.curated_course_node_type, 'Organizational structures, span of control, authority, delegation, centralization, and coordination', null, 2),
  ('59ae9d6c-7ba2-43de-9555-a066ec5adac8', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'b313a3da-cc36-4cdf-88c4-3954b46e5331', 'subtopic'::public.curated_course_node_type, 'Foodservice sectors and stakeholder context', 'Different settings have different missions, payment models, constraints, and definitions of value.', 2),
  ('bdfece02-66a0-4474-a37b-e361c9efa13a', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '59ae9d6c-7ba2-43de-9555-a066ec5adac8', 'concept'::public.curated_course_node_type, 'Acute care, long-term care, schools, universities, corrections, military, community programs, and commercial operations', null, 0),
  ('81558817-7320-44cd-a1a0-e422806b3c8e', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '59ae9d6c-7ba2-43de-9555-a066ec5adac8', 'concept'::public.curated_course_node_type, 'Patients, residents, students, customers, caregivers, staff, administrators, regulators, suppliers, and communities', null, 1),
  ('a5a96b10-67d9-4c0b-a922-a2c77318a209', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '59ae9d6c-7ba2-43de-9555-a066ec5adac8', 'concept'::public.curated_course_node_type, 'Self-operation, contract management, commissary, satellite, and shared-service models', null, 2),
  ('23bcceb3-d090-4ff2-82f9-2d5538b4d3f7', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', null, 'topic'::public.curated_course_node_type, 'Strategy, Governance, Ethics, and Regulation', 'Foodservice leaders translate an organization''s mission into lawful, ethical, and measurable operating choices. This section develops strategic judgment and the ability to navigate accountability across health, nutrition, labor, procurement, and business requirements.', 1),
  ('08adb575-f76e-42c3-8212-2bd2dbdfe13f', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '23bcceb3-d090-4ff2-82f9-2d5538b4d3f7', 'subtopic'::public.curated_course_node_type, 'Strategic planning and environmental analysis', 'Students learn to set priorities using evidence about the organization and its environment.', 0),
  ('f2f48f24-bb35-446f-bfb3-e81d93f7c896', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '08adb575-f76e-42c3-8212-2bd2dbdfe13f', 'concept'::public.curated_course_node_type, 'Needs assessment, stakeholder analysis, SWOT, PESTLE, and scenario planning', null, 0),
  ('dacc4f6e-5acc-4266-a4d7-d3732df916fb', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '08adb575-f76e-42c3-8212-2bd2dbdfe13f', 'concept'::public.curated_course_node_type, 'Strategic goals, key results, service-line planning, and implementation road maps', null, 1),
  ('947f2408-4b1d-4d72-af6f-895f3eb33033', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '08adb575-f76e-42c3-8212-2bd2dbdfe13f', 'concept'::public.curated_course_node_type, 'Benchmarking, competitive positioning, partnerships, and change readiness', null, 2),
  ('516201b0-f508-4424-b353-7c94378be565', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '23bcceb3-d090-4ff2-82f9-2d5538b4d3f7', 'subtopic'::public.curated_course_node_type, 'Governance, law, and accreditation', 'Managers must identify which authority applies and convert requirements into daily controls.', 1),
  ('3a9542a9-20c9-469b-8201-766b8b1cbcce', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '516201b0-f508-4424-b353-7c94378be565', 'concept'::public.curated_course_node_type, 'Federal, state/provincial, local, institutional, and accreditation requirements', null, 0),
  ('16ee9046-72e7-4173-826c-92e01c900679', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '516201b0-f508-4424-b353-7c94378be565', 'concept'::public.curated_course_node_type, 'FDA Food Code as a model; health department adoption and local variation', null, 1),
  ('add1111b-6a86-4cfa-b59f-26cd0fab1713', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '516201b0-f508-4424-b353-7c94378be565', 'concept'::public.curated_course_node_type, 'Health-care, school-meal, labor, accessibility, privacy, environmental, and fire/building requirements', null, 2),
  ('fb3c288a-9ca7-4038-bbe0-229cea68e3c2', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '516201b0-f508-4424-b353-7c94378be565', 'concept'::public.curated_course_node_type, 'Licensure, inspections, permits, documentation, corrective action, and record retention', null, 3),
  ('04dd537e-8cba-4eaa-9cba-75ab34eafbb6', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '23bcceb3-d090-4ff2-82f9-2d5538b4d3f7', 'subtopic'::public.curated_course_node_type, 'Ethics, equity, and professional accountability', 'Students examine whose needs are served, who bears risk, and how transparent decisions protect trust.', 2),
  ('707cc458-0caa-46a7-9790-33bc6ea614f3', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '04dd537e-8cba-4eaa-9cba-75ab34eafbb6', 'concept'::public.curated_course_node_type, 'Dietetics codes of ethics, conflicts of interest, stewardship, and truthful communication', null, 0),
  ('23ffe545-023e-4ab3-808e-30623c798ce0', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '04dd537e-8cba-4eaa-9cba-75ab34eafbb6', 'concept'::public.curated_course_node_type, 'Food and nutrition security, dignity, cultural safety, disability access, and equitable service design', null, 1),
  ('7a113e37-0ce6-4324-af71-e38a7b33ff38', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '04dd537e-8cba-4eaa-9cba-75ab34eafbb6', 'concept'::public.curated_course_node_type, 'Vendor relationships, gifts, bid integrity, whistleblowing, and responsible data use', null, 2),
  ('3683af37-1d60-4e99-baa3-29bcde08b6ad', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', null, 'topic'::public.curated_course_node_type, 'Menu Planning for Nutrition, Culture, and Operations', 'The menu is the operation''s central planning document: it shapes nutrition, purchasing, labor, equipment, cost, safety, satisfaction, and waste. Students design menus that are nutritionally appropriate, culturally responsive, feasible, and appealing.', 2),
  ('f7219aaf-8f82-4f3d-94c5-f150098921af', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '3683af37-1d60-4e99-baa3-29bcde08b6ad', 'subtopic'::public.curated_course_node_type, 'Menu goals and planning frameworks', 'Students translate population needs and organizational constraints into a coherent menu pattern.', 0),
  ('70f3b654-adea-4a41-a579-5b7fce12b820', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'f7219aaf-8f82-4f3d-94c5-f150098921af', 'concept'::public.curated_course_node_type, 'Cycle, static, selective, nonselective, room-service, à la carte, and emergency menus', null, 0),
  ('26e6306b-d031-4e24-bbb5-a6d727c964c1', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'f7219aaf-8f82-4f3d-94c5-f150098921af', 'concept'::public.curated_course_node_type, 'Population assessment, nutrient standards, meal patterns, therapeutic requirements, and service objectives', null, 1),
  ('50f133f1-898d-4ac9-a0e4-5792db636d82', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'f7219aaf-8f82-4f3d-94c5-f150098921af', 'concept'::public.curated_course_node_type, 'Variety, balance, color, texture, flavor, temperature, seasonality, availability, and repetition', null, 2),
  ('7a36455f-8f24-4ccc-9273-6baa8e5ab456', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '3683af37-1d60-4e99-baa3-29bcde08b6ad', 'subtopic'::public.curated_course_node_type, 'Inclusive and person-centered menus', 'Menus should support health while respecting identity, autonomy, access, and lived experience.', 1),
  ('ab025dc7-f2a6-4a32-9872-b30c4164b8be', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '7a36455f-8f24-4ccc-9273-6baa8e5ab456', 'concept'::public.curated_course_node_type, 'Cultural and religious foodways; regional and Indigenous food knowledge', null, 0),
  ('1f641acb-4d11-4a13-a6dd-87f6daeccfc6', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '7a36455f-8f24-4ccc-9273-6baa8e5ab456', 'concept'::public.curated_course_node_type, 'Allergens, intolerances, texture modification, dysphagia, sensory needs, and disability access', null, 1),
  ('c75d7938-6b7f-4464-bd95-eb0d06688c3c', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '7a36455f-8f24-4ccc-9273-6baa8e5ab456', 'concept'::public.curated_course_node_type, 'Plant-forward, vegetarian, vegan, halal, kosher, and other values-based patterns', null, 2),
  ('0481e092-524c-49e0-b930-d33beca13841', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '7a36455f-8f24-4ccc-9273-6baa8e5ab456', 'concept'::public.curated_course_node_type, 'Plain-language naming, multilingual communication, informed choice, and dignity', null, 3),
  ('f8d1165a-0dba-4613-98b4-c66660857a93', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '3683af37-1d60-4e99-baa3-29bcde08b6ad', 'subtopic'::public.curated_course_node_type, 'Menu engineering and validation', 'Students test whether a menu can be executed consistently within nutrition, cost, labor, equipment, and supply constraints.', 2),
  ('68d03600-acd5-4686-9483-ca5dce5108d1', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'f8d1165a-0dba-4613-98b4-c66660857a93', 'concept'::public.curated_course_node_type, 'Nutrient analysis, recipe links, portion standards, production feasibility, and service timing', null, 0);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('38f0c7aa-e1f6-4996-b14c-cdd9fec14410', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'f8d1165a-0dba-4613-98b4-c66660857a93', 'concept'::public.curated_course_node_type, 'Contribution margin, popularity, menu mix, price sensitivity, and cross-utilization', null, 1),
  ('106856f4-6060-4bc4-99c6-f4c2be9a490e', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'f8d1165a-0dba-4613-98b4-c66660857a93', 'concept'::public.curated_course_node_type, 'Plate waste, acceptability, complaints, substitutions, and structured menu review', null, 2),
  ('97d4ca67-0e87-4474-a999-49ca9c60a4e9', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', null, 'topic'::public.curated_course_node_type, 'Forecasting, Procurement, Receiving, and Inventory', 'Reliable supply begins with demand forecasts and ends with controlled inventory. This section teaches students to buy the right quality and quantity, at the right time and total cost, while protecting safety, ethics, and continuity.', 3),
  ('19f16755-3596-4b65-9426-153510d79c41', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '97d4ca67-0e87-4474-a999-49ca9c60a4e9', 'subtopic'::public.curated_course_node_type, 'Demand forecasting and purchasing quantities', 'Forecasts convert historical demand and upcoming conditions into defensible production and purchasing decisions.', 0),
  ('5fbfb734-d245-48e1-b330-31a56c1c9231', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '19f16755-3596-4b65-9426-153510d79c41', 'concept'::public.curated_course_node_type, 'Historical usage, census/enrollment, reservations, day-of-week, seasonality, events, weather, and promotions', null, 0),
  ('ea32ffcf-aec9-490c-a1d4-2b0ecff2b48a', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '19f16755-3596-4b65-9426-153510d79c41', 'concept'::public.curated_course_node_type, 'Moving averages, forecasting error, safety stock, par levels, yield, portion size, and edible-portion calculations', null, 1),
  ('7e11f4af-c0ec-4270-ab9b-8a866545176d', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '19f16755-3596-4b65-9426-153510d79c41', 'concept'::public.curated_course_node_type, 'Make-or-buy analysis, centralized versus decentralized purchasing, and cooperative purchasing', null, 2),
  ('83fdee14-270f-4407-b76d-3fc4e5fc60d5', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '97d4ca67-0e87-4474-a999-49ca9c60a4e9', 'subtopic'::public.curated_course_node_type, 'Specifications, sourcing, and supplier management', 'Clear specifications and fair selection processes reduce ambiguity, risk, and hidden cost.', 1),
  ('794136be-f995-4c02-8be0-40f3991aa884', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '83fdee14-270f-4407-b76d-3fc4e5fc60d5', 'concept'::public.curated_course_node_type, 'Product identity, grade, size, pack, quality, nutrition, allergen, sustainability, delivery, and acceptance criteria', null, 0),
  ('1db83aa6-5cba-4ac2-8f61-54bc4d17bce1', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '83fdee14-270f-4407-b76d-3fc4e5fc60d5', 'concept'::public.curated_course_node_type, 'Informal quotes, competitive bids, requests for proposal, contracts, and public-procurement rules', null, 1),
  ('d7c8861e-e404-4064-bfca-9ee91fd3dc65', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '83fdee14-270f-4407-b76d-3fc4e5fc60d5', 'concept'::public.curated_course_node_type, 'Supplier qualification, audits, performance scorecards, local/seasonal sourcing, and contingency suppliers', null, 2),
  ('91c2a455-da0d-439d-9919-0b32de30d1ad', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '83fdee14-270f-4407-b76d-3fc4e5fc60d5', 'concept'::public.curated_course_node_type, 'Total cost of ownership, price volatility, substitutions, recalls, and supply-chain transparency', null, 3),
  ('845117a9-a40f-48bc-aa1d-51dbf04a1bbf', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '97d4ca67-0e87-4474-a999-49ca9c60a4e9', 'subtopic'::public.curated_course_node_type, 'Receiving, storage, and inventory control', 'Students create controls that protect product integrity, traceability, cash, and availability.', 2),
  ('c9145afe-b55d-4c03-9c2f-5191f90b3b58', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '845117a9-a40f-48bc-aa1d-51dbf04a1bbf', 'concept'::public.curated_course_node_type, 'Receiving schedules, inspection, temperatures, weights/counts, documentation, rejection, and discrepancy resolution', null, 0),
  ('cd839d4b-7969-49bd-9c41-872826b227bf', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '845117a9-a40f-48bc-aa1d-51dbf04a1bbf', 'concept'::public.curated_course_node_type, 'Dry, refrigerated, frozen, chemical, allergen, and secure storage requirements', null, 1),
  ('f330db39-d0fe-4c21-9d5a-470aa7598fa4', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '845117a9-a40f-48bc-aa1d-51dbf04a1bbf', 'concept'::public.curated_course_node_type, 'FIFO/FEFO, perpetual and physical inventory, valuation, turnover, shrinkage, theft, and cycle counts', null, 2),
  ('4d877b6e-1f4c-42fa-befa-b1219d6798b0', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '845117a9-a40f-48bc-aa1d-51dbf04a1bbf', 'concept'::public.curated_course_node_type, 'Traceability, lot codes, recall readiness, and inventory-management technology', null, 3),
  ('350e7bf7-d155-430b-878e-4a675fdd9051', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', null, 'topic'::public.curated_course_node_type, 'Production Planning, Standardization, and Process Control', 'Production management converts the menu and forecast into safe, consistent meals with controlled time, labor, yield, and quality. Students learn to design work rather than rely on last-minute effort.', 4),
  ('b2b2db6c-9d26-4555-99c6-56465feba9cb', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '350e7bf7-d155-430b-878e-4a675fdd9051', 'subtopic'::public.curated_course_node_type, 'Production systems and scheduling', 'Students match production methods and timing to volume, quality, service, and facility constraints.', 0),
  ('5eef9c0a-dbd5-451b-a6d9-3a41a58e6987', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'b2b2db6c-9d26-4555-99c6-56465feba9cb', 'concept'::public.curated_course_node_type, 'Conventional, ready-prepared/cook-chill, commissary, assembly-serve, and sous-vide systems', null, 0),
  ('3c86d921-b22f-48fb-ae53-6228165f21f6', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'b2b2db6c-9d26-4555-99c6-56465feba9cb', 'concept'::public.curated_course_node_type, 'Production schedules, batch cooking, work sequencing, critical paths, bottlenecks, and capacity', null, 1),
  ('d041eeda-78f9-45dc-bf60-ff40171e874d', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'b2b2db6c-9d26-4555-99c6-56465feba9cb', 'concept'::public.curated_course_node_type, 'Census changes, substitutions, overproduction, underproduction, and end-of-service decisions', null, 2),
  ('c2b87aa9-39ea-4ad3-b963-e3baaebc330b', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '350e7bf7-d155-430b-878e-4a675fdd9051', 'subtopic'::public.curated_course_node_type, 'Standardized recipes, scaling, and yield', 'A standardized recipe is a control tool for nutrition, cost, allergens, training, purchasing, and consistency.', 1),
  ('07cd03a5-a7ac-49a6-a262-365897b5ef9c', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'c2b87aa9-39ea-4ad3-b963-e3baaebc330b', 'concept'::public.curated_course_node_type, 'Recipe format, ingredients, procedures, equipment, critical limits, portions, plating, and service notes', null, 0),
  ('bcd408b1-0bf3-42ea-bb6f-020a522ebadc', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'c2b87aa9-39ea-4ad3-b963-e3baaebc330b', 'concept'::public.curated_course_node_type, 'Weight versus volume, conversion factors, baker''s percentage, yield tests, edible portion, and cooking loss', null, 1),
  ('a75d5de6-5923-416e-97b6-10997495a204', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'c2b87aa9-39ea-4ad3-b963-e3baaebc330b', 'concept'::public.curated_course_node_type, 'Recipe verification, sensory evaluation, nutrient analysis, cost calculation, version control, and approval', null, 2),
  ('6095349a-d4bb-49c5-8503-e9b7eee9d97b', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '350e7bf7-d155-430b-878e-4a675fdd9051', 'subtopic'::public.curated_course_node_type, 'Work methods and operational control', 'Students analyze tasks and flows to improve safety, productivity, ergonomics, and quality.', 2),
  ('bbe4196d-c094-41bc-89f1-2da23e1cab8a', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '6095349a-d4bb-49c5-8503-e9b7eee9d97b', 'concept'::public.curated_course_node_type, 'Flow diagrams, process charts, time studies, work simplification, motion economy, and standard work', null, 0),
  ('14b6d029-73ff-44c0-b220-2636695d26c8', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '6095349a-d4bb-49c5-8503-e9b7eee9d97b', 'concept'::public.curated_course_node_type, 'Mise en place, workplace organization, visual controls, handoffs, and mistake-proofing', null, 1),
  ('f575802a-3084-4223-bd45-a872c556a6e0', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '6095349a-d4bb-49c5-8503-e9b7eee9d97b', 'concept'::public.curated_course_node_type, 'Productivity standards, meals per labor hour, schedule adherence, and variance response', null, 2),
  ('972fab11-9dee-42cc-add0-22e0d12efb3f', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', null, 'topic'::public.curated_course_node_type, 'Food Safety, Sanitation, Security, and Risk Management', 'Managers build systems that prevent illness and injury rather than merely reacting to inspection findings. This section integrates active managerial control, sanitation, occupational safety, food defense, and risk analysis.', 5),
  ('62dea549-c4f3-44a6-a655-77a45417da7a', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '972fab11-9dee-42cc-add0-22e0d12efb3f', 'subtopic'::public.curated_course_node_type, 'Active managerial control and HACCP', 'Students identify hazards, choose preventive controls, verify performance, and act when limits are missed.', 0),
  ('99786043-6d41-46f5-b6e4-b322bfb32bda', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '62dea549-c4f3-44a6-a655-77a45417da7a', 'concept'::public.curated_course_node_type, 'Biological, chemical, physical, allergen, and radiological hazards', null, 0),
  ('b56d3cf3-3397-44d0-9d1b-dd86ee613289', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '62dea549-c4f3-44a6-a655-77a45417da7a', 'concept'::public.curated_course_node_type, 'Process approach, prerequisite programs, HACCP principles, critical limits, monitoring, corrective action, verification, and records', null, 1),
  ('18c23e06-c9fa-4e76-bef5-e80e337ceb1f', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '62dea549-c4f3-44a6-a655-77a45417da7a', 'concept'::public.curated_course_node_type, 'Person in charge, employee health, hand hygiene, time-temperature control, cooling, reheating, and cross-contamination prevention', null, 2),
  ('22057c90-9e3d-49de-909a-96c6c09665f8', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '972fab11-9dee-42cc-add0-22e0d12efb3f', 'subtopic'::public.curated_course_node_type, 'Sanitation and environmental hygiene', 'Effective sanitation combines validated chemistry and technique with schedules, verification, and a culture of ownership.', 1),
  ('5e42029e-aced-414e-9487-b13f1ec100bd', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '22057c90-9e3d-49de-909a-96c6c09665f8', 'concept'::public.curated_course_node_type, 'Cleaning versus sanitizing, water quality, detergent/sanitizer selection, concentration, contact time, and material compatibility', null, 0),
  ('3dd3c00b-4b36-4beb-82ce-8bd3b00efeea', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '22057c90-9e3d-49de-909a-96c6c09665f8', 'concept'::public.curated_course_node_type, 'Master sanitation schedules, warewashing, equipment disassembly, pest management, waste areas, and environmental monitoring', null, 1),
  ('9c868f1e-9086-4678-b4d9-d89487212856', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '22057c90-9e3d-49de-909a-96c6c09665f8', 'concept'::public.curated_course_node_type, 'ATP/chemical checks, inspection, trend analysis, and corrective/preventive action', null, 2),
  ('d08e2857-2458-44c4-b340-5f48fd9cc548', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '972fab11-9dee-42cc-add0-22e0d12efb3f', 'subtopic'::public.curated_course_node_type, 'Safety, security, allergens, and crisis response', 'Students manage interconnected risks to employees, consumers, facilities, and continuity.', 2);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('3be37603-0027-4086-b500-dd735a8b1ec3', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'd08e2857-2458-44c4-b340-5f48fd9cc548', 'concept'::public.curated_course_node_type, 'Occupational hazards, ergonomics, slips/falls, burns, cuts, chemicals, lockout/tagout awareness, and incident investigation', null, 0),
  ('6ea67c8f-49e7-483e-b6f8-9fed3d7557de', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'd08e2857-2458-44c4-b340-5f48fd9cc548', 'concept'::public.curated_course_node_type, 'Allergen control plans, ingredient review, segregation, change management, communication, and emergency treatment protocols', null, 1),
  ('fd8b0a95-8bc5-49c7-8c19-61b4e8cdf468', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'd08e2857-2458-44c4-b340-5f48fd9cc548', 'concept'::public.curated_course_node_type, 'Food defense, intentional adulteration awareness, access control, cybersecurity interfaces, utility failure, boil-water events, outbreaks, recalls, and crisis communication', null, 2),
  ('17ff80b4-2cf5-46c8-bb00-e21234ec85bf', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', null, 'topic'::public.curated_course_node_type, 'Facilities, Equipment, Workflow, and Capacity', 'Facilities and equipment encode operational choices for decades. Students learn to evaluate layout, capacity, utilities, maintainability, accessibility, safety, and life-cycle value before recommending capital investment.', 6),
  ('5085ccb9-de16-4aea-9a90-aa6147482663', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '17ff80b4-2cf5-46c8-bb00-e21234ec85bf', 'subtopic'::public.curated_course_node_type, 'Facility programming and workflow design', 'Students begin with services, volumes, processes, and flows before drawing a layout.', 0),
  ('4301879d-364e-4d8b-9772-81a96e58e75c', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '5085ccb9-de16-4aea-9a90-aa6147482663', 'concept'::public.curated_course_node_type, 'Program of requirements, adjacency, zoning, receiving-to-service flow, clean/dirty separation, and traffic analysis', null, 0),
  ('9cefb7a4-a7e0-4093-bfe3-50a9f0c4a83a', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '5085ccb9-de16-4aea-9a90-aa6147482663', 'concept'::public.curated_course_node_type, 'Employee, food, dishware, waste, patient/customer, and information flows', null, 1),
  ('c28bc303-0461-466b-ac83-6ed87235efa4', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '5085ccb9-de16-4aea-9a90-aa6147482663', 'concept'::public.curated_course_node_type, 'Universal design, ergonomics, visibility, acoustics, wayfinding, staff welfare, and security', null, 2),
  ('39467bc5-cd90-4144-bb4c-ec710c264e47', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '17ff80b4-2cf5-46c8-bb00-e21234ec85bf', 'subtopic'::public.curated_course_node_type, 'Equipment selection and capacity analysis', 'Equipment should fit the menu, process, peak load, workforce, utilities, and maintenance capability.', 1),
  ('b1df1c21-09f8-4537-9846-d400ce8cd8b8', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '39467bc5-cd90-4144-bb4c-ec710c264e47', 'concept'::public.curated_course_node_type, 'Performance specifications, rated versus usable capacity, throughput, bottlenecks, redundancy, and future demand', null, 0),
  ('de3a8156-4c3a-41bc-839d-707c9be2f141', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '39467bc5-cd90-4144-bb4c-ec710c264e47', 'concept'::public.curated_course_node_type, 'Energy, water, ventilation, drainage, electrical/gas loads, controls, interoperability, and training', null, 1),
  ('f4b75c35-6c9d-4629-beb1-fc002964e44d', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '39467bc5-cd90-4144-bb4c-ec710c264e47', 'concept'::public.curated_course_node_type, 'Purchase price, installation, maintenance, downtime, useful life, resale, and life-cycle cost', null, 2),
  ('de972231-041c-44ac-a161-3531ca4a9c6e', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '17ff80b4-2cf5-46c8-bb00-e21234ec85bf', 'subtopic'::public.curated_course_node_type, 'Maintenance and capital planning', 'Preventive maintenance and replacement planning protect safety, uptime, quality, and budgets.', 2),
  ('c79d7bf5-1265-44d2-b5fb-d9dca67ed069', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'de972231-041c-44ac-a161-3531ca4a9c6e', 'concept'::public.curated_course_node_type, 'Asset registers, preventive and predictive maintenance, inspections, calibration, and service records', null, 0),
  ('db7d9ead-01b3-4543-a841-a9b784e5cfe8', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'de972231-041c-44ac-a161-3531ca4a9c6e', 'concept'::public.curated_course_node_type, 'Work-order priority, spare parts, service agreements, vendor management, and downtime contingency', null, 1),
  ('9aa395a2-6d0d-4371-afc2-f0b1f1930ce0', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'de972231-041c-44ac-a161-3531ca4a9c6e', 'concept'::public.curated_course_node_type, 'Condition assessment, capital requests, depreciation concepts, replacement cycles, and commissioning', null, 2),
  ('63d105a4-405d-4e84-9c56-48f77ca51543', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', null, 'topic'::public.curated_course_node_type, 'Distribution, Service, and Customer Experience', 'A well-produced meal only creates value if it reaches the right person, at the right time, temperature, quality, and level of dignity. This section examines distribution logistics and service design across institutional settings.', 7),
  ('e7016f06-4de7-4fcf-8a43-60aec3af27a3', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '63d105a4-405d-4e84-9c56-48f77ca51543', 'subtopic'::public.curated_course_node_type, 'Distribution and meal-delivery systems', 'Students compare systems by temperature control, distance, labor, accuracy, flexibility, and experience.', 0),
  ('8fd4a614-322b-4933-b4c3-88de2525d47e', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'e7016f06-4de7-4fcf-8a43-60aec3af27a3', 'concept'::public.curated_course_node_type, 'Centralized and decentralized trayline, bulk service, room service, satellite, cafeteria, mobile, delivery, and vending', null, 0),
  ('b30ebe32-772a-47ec-97ae-792070ad196e', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'e7016f06-4de7-4fcf-8a43-60aec3af27a3', 'concept'::public.curated_course_node_type, 'Hot/cold holding, transport, staging, tray accuracy, ticketing, routing, dispatch, and chain of custody', null, 1),
  ('d3583f67-c6a9-471c-939b-9f797deab106', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'e7016f06-4de7-4fcf-8a43-60aec3af27a3', 'concept'::public.curated_course_node_type, 'Patient census, diet-order interfaces, late trays, missed meals, nourishments, and disaster feeding', null, 2),
  ('ede3b775-76f3-44f3-910f-1b55f9aee51b', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '63d105a4-405d-4e84-9c56-48f77ca51543', 'subtopic'::public.curated_course_node_type, 'Service design and experience management', 'Students map the service journey to remove friction and improve trust, access, and satisfaction.', 1),
  ('708eb13a-d758-4dc4-bde7-0b4b3e66bbca', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'ede3b775-76f3-44f3-910f-1b55f9aee51b', 'concept'::public.curated_course_node_type, 'Service blueprints, touchpoints, queue design, wait time, recovery, and moments of truth', null, 0),
  ('c96b035e-d068-454a-be67-5d08b3fe866b', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'ede3b775-76f3-44f3-910f-1b55f9aee51b', 'concept'::public.curated_course_node_type, 'Hospitality behaviors, empathy, privacy, trauma-informed interaction, and interprofessional communication', null, 1),
  ('fcd7c18c-9054-4b0a-a142-3cce9ee0927d', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'ede3b775-76f3-44f3-910f-1b55f9aee51b', 'concept'::public.curated_course_node_type, 'Choice architecture, retail displays, signage, digital ordering, and inclusive wayfinding', null, 2),
  ('ecc6318f-5d1d-47ff-8650-0fdd78b52a7c', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '63d105a4-405d-4e84-9c56-48f77ca51543', 'subtopic'::public.curated_course_node_type, 'Measuring service quality', 'Feedback is useful when it is timely, representative, actionable, and connected to operational data.', 2),
  ('481e8a70-cd3a-4efb-99c1-b7cb36922ba4', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'ecc6318f-5d1d-47ff-8650-0fdd78b52a7c', 'concept'::public.curated_course_node_type, 'Satisfaction surveys, interviews, focus groups, complaints, compliments, observation, and plate-waste measures', null, 0),
  ('fd5bdc82-0f3b-41f4-b207-2f012a3db0ab', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'ecc6318f-5d1d-47ff-8650-0fdd78b52a7c', 'concept'::public.curated_course_node_type, 'Reliability, responsiveness, assurance, empathy, tangibles, and expectation gaps', null, 1),
  ('c7d1d580-6157-4381-bc24-f5416caa2a60', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'ecc6318f-5d1d-47ff-8650-0fdd78b52a7c', 'concept'::public.curated_course_node_type, 'Response bias, accessibility, segmentation, service recovery, and closing the feedback loop', null, 2),
  ('ed7999d6-5d53-418f-af49-65a1a50ece68', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', null, 'topic'::public.curated_course_node_type, 'Financial Management, Budgeting, and Cost Control', 'Financial literacy allows nutrition professionals to protect quality and access while stewarding scarce resources. Students learn to read a budget, explain variance, control costs, and build a defensible business case.', 8),
  ('2a0ae512-b2ca-43b2-aefd-d880e27d0bae', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'ed7999d6-5d53-418f-af49-65a1a50ece68', 'subtopic'::public.curated_course_node_type, 'Financial statements and budgeting', 'Students connect operating decisions to revenue, expense, assets, and cash consequences.', 0),
  ('8e5569fa-09bd-41ce-a067-f68752fd28d1', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '2a0ae512-b2ca-43b2-aefd-d880e27d0bae', 'concept'::public.curated_course_node_type, 'Operating and capital budgets; incremental, flexible, zero-based, and activity-based approaches', null, 0),
  ('23e27aa4-cc98-4a6b-8eba-ba5d2d589ae1', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '2a0ae512-b2ca-43b2-aefd-d880e27d0bae', 'concept'::public.curated_course_node_type, 'Income statement, balance sheet, cash-flow concepts, chart of accounts, and responsibility centers', null, 1),
  ('1874a97c-3b4f-4c9d-b38c-12aa6817d41d', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '2a0ae512-b2ca-43b2-aefd-d880e27d0bae', 'concept'::public.curated_course_node_type, 'Volume assumptions, inflation, labor contracts, depreciation, grants, subsidies, and reimbursement context', null, 2),
  ('7053f844-ae6a-4e3d-ae70-52c5721d29d8', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'ed7999d6-5d53-418f-af49-65a1a50ece68', 'subtopic'::public.curated_course_node_type, 'Food, labor, and operating cost control', 'Cost control means understanding why actual results differ from plan and correcting causes without compromising safety or care.', 1),
  ('42dc8d68-0a8f-4669-9809-5734ab9832d8', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '7053f844-ae6a-4e3d-ae70-52c5721d29d8', 'concept'::public.curated_course_node_type, 'Standard versus actual food cost, cost per meal, contribution margin, food-cost percentage, yield, waste, and price/usage variance', null, 0),
  ('071a0d7e-5cc5-42b4-8c82-58353813be65', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '7053f844-ae6a-4e3d-ae70-52c5721d29d8', 'concept'::public.curated_course_node_type, 'Labor hours, wages, benefits, overtime, productivity, schedule variance, and skill mix', null, 1),
  ('588a1b7a-9b7f-430e-96ff-b6938076099c', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '7053f844-ae6a-4e3d-ae70-52c5721d29d8', 'concept'::public.curated_course_node_type, 'Utilities, supplies, maintenance, contracts, fixed/variable/semivariable costs, and controllable/uncontrollable costs', null, 2),
  ('f499487e-e015-4d72-850a-ae36220544ae', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'ed7999d6-5d53-418f-af49-65a1a50ece68', 'subtopic'::public.curated_course_node_type, 'Feasibility and investment decisions', 'Students combine demand, cost, capacity, risk, and mission fit to assess a proposed service or capital project.', 2),
  ('2773e010-0668-416c-b703-09ce073223d1', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'f499487e-e015-4d72-850a-ae36220544ae', 'concept'::public.curated_course_node_type, 'Market/needs analysis, technical feasibility, operating model, staffing, equipment, supply, and implementation assumptions', null, 0);
