values
  ('e45448d4-e23f-40af-b692-672efd7c9ee8', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'f499487e-e015-4d72-850a-ae36220544ae', 'concept'::public.curated_course_node_type, 'Break-even, cost-benefit, payback, return on investment, sensitivity, scenario, and risk analysis', null, 1),
  ('e5e72031-e51b-43c2-bc8d-2b9f75a7ac8d', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'f499487e-e015-4d72-850a-ae36220544ae', 'concept'::public.curated_course_node_type, 'Business case, budget narrative, nonfinancial benefits, equity impacts, and recommendation limits', null, 2),
  ('30ce7d6b-f1a7-4e81-94f0-b2c80037fe96', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', null, 'topic'::public.curated_course_node_type, 'Workforce Planning, Leadership, and Human Resources', 'Foodservice performance depends on people working in demanding, diverse, and safety-critical environments. This section develops equitable workforce systems and leadership practices that support competence, well-being, accountability, and retention.', 9),
  ('29b3e570-362d-461f-8a22-3f2a0feb8e92', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '30ce7d6b-f1a7-4e81-94f0-b2c80037fe96', 'subtopic'::public.curated_course_node_type, 'Workforce planning and staffing', 'Students translate workload and service requirements into roles, schedules, and coverage.', 0),
  ('6b5e8730-c333-4b50-a025-be888457eba8', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '29b3e570-362d-461f-8a22-3f2a0feb8e92', 'concept'::public.curated_course_node_type, 'Job analysis, job descriptions, competencies, staffing patterns, full-time equivalents, relief factors, and skill mix', null, 0),
  ('e2b337bd-75f4-4ba2-a816-1688e619839d', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '29b3e570-362d-461f-8a22-3f2a0feb8e92', 'concept'::public.curated_course_node_type, 'Scheduling, availability, seniority, overtime, cross-training, call-outs, peak demand, and contingency staffing', null, 1),
  ('f6757975-a1c4-4220-9e31-a72a8faa842e', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '29b3e570-362d-461f-8a22-3f2a0feb8e92', 'concept'::public.curated_course_node_type, 'Recruitment, selection, onboarding, credential verification, and lawful hiring practices', null, 2),
  ('5db764c3-b76b-4241-a9c1-c1cc61e9c260', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '30ce7d6b-f1a7-4e81-94f0-b2c80037fe96', 'subtopic'::public.curated_course_node_type, 'Leadership, communication, and labor relations', 'Students practice leading across roles, shifts, cultures, and professional disciplines.', 1),
  ('7ed871dc-9c61-40ca-95c8-54a5bb2fa5db', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '5db764c3-b76b-4241-a9c1-c1cc61e9c260', 'concept'::public.curated_course_node_type, 'Leadership styles, emotional intelligence, psychological safety, motivation, delegation, coaching, and accountability', null, 0),
  ('ad995a15-a2ab-41fd-8a23-c9b2fbc197fa', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '5db764c3-b76b-4241-a9c1-c1cc61e9c260', 'concept'::public.curated_course_node_type, 'Briefings, huddles, handoffs, feedback, conflict resolution, difficult conversations, and change communication', null, 1),
  ('be8fafba-7be3-47a8-b6a1-e2147b11387f', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '5db764c3-b76b-4241-a9c1-c1cc61e9c260', 'concept'::public.curated_course_node_type, 'Employment standards, collective agreements, progressive discipline, grievances, harassment prevention, and documentation', null, 2),
  ('04a730e7-d4d4-48cb-b975-3dd21bf89d9e', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '30ce7d6b-f1a7-4e81-94f0-b2c80037fe96', 'subtopic'::public.curated_course_node_type, 'Training, performance, and well-being', 'A learning system makes expected performance visible, teaches it, verifies competence, and supports improvement.', 2),
  ('7725e2ab-710c-4a23-aa59-4a85fb6d33a0', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '04a730e7-d4d4-48cb-b975-3dd21bf89d9e', 'concept'::public.curated_course_node_type, 'Training-needs analysis, adult learning, demonstrations, language/literacy access, job aids, and teach-back', null, 0),
  ('fa7b3f1e-6761-4d20-a757-4fdcf12febd1', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '04a730e7-d4d4-48cb-b975-3dd21bf89d9e', 'concept'::public.curated_course_node_type, 'Competency checks, probation, performance standards, appraisal, recognition, development plans, and succession', null, 1),
  ('61ef7520-fb44-49fe-86fe-9ffd183b6ae7', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '04a730e7-d4d4-48cb-b975-3dd21bf89d9e', 'concept'::public.curated_course_node_type, 'Burnout, workload, fatigue, injury prevention, belonging, retention, and employee-engagement measures', null, 2),
  ('8f4a2cc2-e93f-4575-aca7-0eaa3834f580', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', null, 'topic'::public.curated_course_node_type, 'Information Systems, Data, and Digital Operations', 'Modern food and nutrition services depend on reliable data moving across clinical, production, purchasing, finance, and customer systems. Students learn to choose useful technology, protect information, and make decisions from trustworthy data.', 10),
  ('2de2a06b-36b5-47e0-b37b-8752c084a450', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '8f4a2cc2-e93f-4575-aca7-0eaa3834f580', 'subtopic'::public.curated_course_node_type, 'Operational information systems', 'Students map how data supports orders, recipes, inventory, production, service, finance, and traceability.', 0),
  ('b640d2f1-a75d-45bd-9c75-9a0fe7c36517', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '2de2a06b-36b5-47e0-b37b-8752c084a450', 'concept'::public.curated_course_node_type, 'Menu and nutrient-analysis software, recipe databases, procurement, inventory, point of sale, scheduling, and maintenance systems', null, 0),
  ('a3d46111-beb6-4d9c-91c0-d4903f92a27c', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '2de2a06b-36b5-47e0-b37b-8752c084a450', 'concept'::public.curated_course_node_type, 'Electronic health record and diet-order interfaces, bedside ordering, tray tickets, and patient identifiers', null, 1),
  ('2a04e20f-acc0-4e14-8105-980093d09567', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '2de2a06b-36b5-47e0-b37b-8752c084a450', 'concept'::public.curated_course_node_type, 'Barcodes, RFID, temperature sensors, digital logs, dashboards, and automation', null, 2),
  ('671a9213-42aa-4afd-9ab1-bb0e1379fe40', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '8f4a2cc2-e93f-4575-aca7-0eaa3834f580', 'subtopic'::public.curated_course_node_type, 'Data governance and cybersecurity', 'Useful information must be accurate, defined, protected, and available to authorized users.', 1),
  ('32077062-4140-4a51-955d-62d005179a2b', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '671a9213-42aa-4afd-9ab1-bb0e1379fe40', 'concept'::public.curated_course_node_type, 'Data dictionaries, master data, validation rules, permissions, audit trails, retention, backups, and downtime procedures', null, 0),
  ('e0fc978c-096a-490b-9cbc-d08b125e1035', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '671a9213-42aa-4afd-9ab1-bb0e1379fe40', 'concept'::public.curated_course_node_type, 'Privacy, minimum necessary access, secure devices, phishing, vendor risk, incident escalation, and business continuity', null, 1),
  ('fe2ee97a-e100-4a70-a055-a64cc2145d8e', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '671a9213-42aa-4afd-9ab1-bb0e1379fe40', 'concept'::public.curated_course_node_type, 'Algorithmic bias, accessibility, informed oversight, automation limits, and human accountability', null, 2),
  ('3aabf61a-0ffa-4eb1-bfaa-446bbfe78525', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '8f4a2cc2-e93f-4575-aca7-0eaa3834f580', 'subtopic'::public.curated_course_node_type, 'Analytics and decision support', 'Students convert operational records into measures that answer a specific management question.', 2),
  ('3134752e-90e9-4ab4-af81-b70c278c4010', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '3aabf61a-0ffa-4eb1-bfaa-446bbfe78525', 'concept'::public.curated_course_node_type, 'Data cleaning, denominators, stratification, run charts, control charts, dashboards, and visualization', null, 0),
  ('f9a420c6-e577-4ab3-8c6d-f806af71af8f', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '3aabf61a-0ffa-4eb1-bfaa-446bbfe78525', 'concept'::public.curated_course_node_type, 'Forecasting, variance analysis, labor/productivity analysis, waste analytics, and demand segmentation', null, 1),
  ('f8b9b728-ad9f-43c0-a882-e9b78ce89477', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '3aabf61a-0ffa-4eb1-bfaa-446bbfe78525', 'concept'::public.curated_course_node_type, 'Correlation versus causation, missingness, bias, uncertainty, data storytelling, and decision thresholds', null, 2),
  ('14ef7e6d-3ffe-4853-a26c-5e230027e55a', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', null, 'topic'::public.curated_course_node_type, 'Quality Improvement and Performance Management', 'Quality improvement turns daily variation, feedback, and incidents into disciplined learning. Students define quality, select measures, study processes, test changes, and sustain gains.', 11),
  ('7fd4b196-392f-4479-9475-457ecdce1857', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '14ef7e6d-3ffe-4853-a26c-5e230027e55a', 'subtopic'::public.curated_course_node_type, 'Quality frameworks and measurement', 'Students create a balanced view of safety, nutrition, experience, workforce, finance, and sustainability.', 0),
  ('ddf36009-a813-4b22-b81f-4694ab888a83', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '7fd4b196-392f-4479-9475-457ecdce1857', 'concept'::public.curated_course_node_type, 'Quality assurance versus quality improvement; structure, process, and outcome measures', null, 0),
  ('13210db7-6fac-42a0-9522-ad0617ac5b22', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '7fd4b196-392f-4479-9475-457ecdce1857', 'concept'::public.curated_course_node_type, 'Key performance indicators, operational definitions, numerator/denominator, targets, benchmarks, and balancing measures', null, 1),
  ('5d614a28-4c97-4363-a7bd-1b6c9756224c', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '7fd4b196-392f-4479-9475-457ecdce1857', 'concept'::public.curated_course_node_type, 'Audit, inspection, survey, direct observation, sampling, validity, reliability, and data timeliness', null, 2),
  ('abd83009-faf4-479a-9cd5-afd4fdc63af8', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '14ef7e6d-3ffe-4853-a26c-5e230027e55a', 'subtopic'::public.curated_course_node_type, 'Process improvement methods', 'Students use structured methods to identify causes and test changes on a manageable scale.', 1),
  ('13ee8773-e1af-4b3f-b210-c16c9cd0e195', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'abd83009-faf4-479a-9cd5-afd4fdc63af8', 'concept'::public.curated_course_node_type, 'Process maps, SIPOC, Pareto charts, fishbone diagrams, five whys, failure mode and effects analysis, and root-cause analysis', null, 0),
  ('3da13cd9-3ce2-4600-9079-132f8c24c551', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'abd83009-faf4-479a-9cd5-afd4fdc63af8', 'concept'::public.curated_course_node_type, 'Plan-Do-Study-Act cycles, Lean waste, standard work, visual management, and mistake-proofing', null, 1),
  ('b279123c-4a09-4357-ae62-fc1e18acdf10', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'abd83009-faf4-479a-9cd5-afd4fdc63af8', 'concept'::public.curated_course_node_type, 'Statistical process control concepts, common- versus special-cause variation, and response plans', null, 2),
  ('0eaa5e14-c980-44af-b348-d73ef22e3dc9', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '14ef7e6d-3ffe-4853-a26c-5e230027e55a', 'subtopic'::public.curated_course_node_type, 'Sustaining and spreading improvement', 'Improvement is not complete until gains are embedded, monitored, and adapted across contexts.', 2),
  ('989b3351-8d84-4e7a-995b-2e3839dca516', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '0eaa5e14-c980-44af-b348-d73ef22e3dc9', 'concept'::public.curated_course_node_type, 'Stakeholder engagement, implementation barriers, change champions, training, policy revision, and resource alignment', null, 0),
  ('3d7c46df-5e38-4362-8844-4eb92324c16f', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '0eaa5e14-c980-44af-b348-d73ef22e3dc9', 'concept'::public.curated_course_node_type, 'Control plans, ownership, audit frequency, feedback, sustainment measures, and relapse response', null, 1);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('b10d39a2-e3cd-419b-a785-acea949e639f', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '0eaa5e14-c980-44af-b348-d73ef22e3dc9', 'concept'::public.curated_course_node_type, 'Pilot versus spread, local adaptation, unintended consequences, equity checks, and lessons learned', null, 2),
  ('9166415c-de3c-4721-949f-2f0d93fce289', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', null, 'topic'::public.curated_course_node_type, 'Sustainability, Waste, and Resilient Food Systems', 'Sustainability requires simultaneous attention to nutrition, environment, labor, community, resilience, and cost. Students learn to make evidence-based changes that avoid shifting burdens elsewhere in the system.', 12),
  ('2530aef6-5584-4abe-94b9-592aa805cbce', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '9166415c-de3c-4721-949f-2f0d93fce289', 'subtopic'::public.curated_course_node_type, 'Sustainable procurement and menu strategy', 'Students evaluate purchasing and menu choices using transparent criteria and a defined functional unit.', 0),
  ('f2f46f11-173d-4cba-b07e-20ef46fdb688', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '2530aef6-5584-4abe-94b9-592aa805cbce', 'concept'::public.curated_course_node_type, 'Plant-forward design, seasonality, local and regional sourcing, certified products, animal welfare, and sustainable seafood', null, 0),
  ('7fef2707-4a6a-4416-93bf-ac06560318e1', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '2530aef6-5584-4abe-94b9-592aa805cbce', 'concept'::public.curated_course_node_type, 'Supplier environmental and labor practices, packaging, transport, traceability, and credible claims', null, 1),
  ('ad6bc166-d34d-4994-aec5-30623c6c02ff', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '2530aef6-5584-4abe-94b9-592aa805cbce', 'concept'::public.curated_course_node_type, 'Life-cycle thinking, nutrition density, cost, acceptability, equity, and tradeoffs', null, 2),
  ('9e87df79-6153-44d6-8dba-8b0597a420ea', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '9166415c-de3c-4721-949f-2f0d93fce289', 'subtopic'::public.curated_course_node_type, 'Food-waste prevention and materials management', 'The preferred strategy is to prevent surplus before managing unavoidable material.', 1),
  ('b5b9f1aa-0772-482e-9b89-7c290eb5a6ad', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '9e87df79-6153-44d6-8dba-8b0597a420ea', 'concept'::public.curated_course_node_type, 'Source reduction, forecasting, portion and batch adjustment, cross-utilization, donation, animal feed, industrial uses, composting, and disposal hierarchy', null, 0),
  ('a317b9dc-ace9-426f-884c-3d797e610d9e', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '9e87df79-6153-44d6-8dba-8b0597a420ea', 'concept'::public.curated_course_node_type, 'Pre-consumer versus post-consumer measurement, waste audits, causes, financial value, and greenhouse-gas implications', null, 1),
  ('12560edc-9f9d-4f82-b14e-8c5c03418f66', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '9e87df79-6153-44d6-8dba-8b0597a420ea', 'concept'::public.curated_course_node_type, 'Safe donation, date-label literacy, reusable serviceware, recycling/compost contamination, and local infrastructure', null, 2),
  ('2f92a913-491f-4248-84fd-279a31f2dd6c', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '9166415c-de3c-4721-949f-2f0d93fce289', 'subtopic'::public.curated_course_node_type, 'Climate adaptation and operational resilience', 'Students prepare systems to continue essential feeding during disruptions and long-term change.', 2),
  ('c8a1473d-2fc1-4a04-85d8-8501d019f10b', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '2f92a913-491f-4248-84fd-279a31f2dd6c', 'concept'::public.curated_course_node_type, 'Climate, extreme weather, water scarcity, energy disruption, crop failure, logistics, price volatility, and workforce risk', null, 0),
  ('9efdb7c2-4722-4d0d-bc7b-3c800b993614', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '2f92a913-491f-4248-84fd-279a31f2dd6c', 'concept'::public.curated_course_node_type, 'Hazard vulnerability analysis, alternate suppliers, emergency menus, stock levels, mutual aid, backup power/water, and communications', null, 1),
  ('d42034b0-1eec-4613-b9b3-cea5bb82da0a', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '2f92a913-491f-4248-84fd-279a31f2dd6c', 'concept'::public.curated_course_node_type, 'Resilience metrics, drills, after-action review, adaptation investment, and community partnerships', null, 2),
  ('00a41581-bcd3-40a8-a232-bf9c27acdfdd', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', null, 'topic'::public.curated_course_node_type, 'Marketing, Communication, and Community Engagement', 'Foodservice managers communicate value, support informed choice, and build relationships with the people affected by the service. Ethical marketing connects evidence and experience without exploiting health fears or vulnerable populations.', 13),
  ('25108e14-3f72-44f6-bb54-3a5d4b896d81', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '00a41581-bcd3-40a8-a232-bf9c27acdfdd', 'subtopic'::public.curated_course_node_type, 'Market and audience understanding', 'Students use research to understand needs, barriers, preferences, and competition before designing a message or service.', 0),
  ('9b18931f-34f4-4faf-a401-37165c15c809', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '25108e14-3f72-44f6-bb54-3a5d4b896d81', 'concept'::public.curated_course_node_type, 'Segmentation by needs and behavior without stereotyping', null, 0),
  ('9764dd3d-edb8-4989-ad9b-168cbd0c61fd', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '25108e14-3f72-44f6-bb54-3a5d4b896d81', 'concept'::public.curated_course_node_type, 'Surveys, interviews, observation, sales/menu-mix data, personas, and journey maps', null, 1),
  ('ef94f23c-780b-40d2-b687-9bb903e6e60d', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '25108e14-3f72-44f6-bb54-3a5d4b896d81', 'concept'::public.curated_course_node_type, 'Market position, value proposition, environmental scan, and service gaps', null, 2),
  ('d499fa12-95a6-4202-bf65-5e81bd3e2851', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '00a41581-bcd3-40a8-a232-bf9c27acdfdd', 'subtopic'::public.curated_course_node_type, 'Integrated and ethical communication', 'Students create accessible messages consistent with nutrition evidence, brand, law, and organizational purpose.', 1),
  ('0cf9bc61-e755-4337-8f8f-e8529184639c', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'd499fa12-95a6-4202-bf65-5e81bd3e2851', 'concept'::public.curated_course_node_type, 'Product, price, place, promotion, people, process, and physical evidence', null, 0),
  ('653df0fa-7b07-4c16-b6ea-7ad40ef3843b', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'd499fa12-95a6-4202-bf65-5e81bd3e2851', 'concept'::public.curated_course_node_type, 'Nutrition and allergen information, claims, plain language, multilingual content, accessibility, and health literacy', null, 1),
  ('2687c41e-8c40-4a76-8433-98f8ce74d1d5', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'd499fa12-95a6-4202-bf65-5e81bd3e2851', 'concept'::public.curated_course_node_type, 'Digital, print, signage, point-of-choice, social media, internal communication, and misinformation response', null, 2),
  ('8573d725-0012-4ab0-ae34-8aa22bac6f6c', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '00a41581-bcd3-40a8-a232-bf9c27acdfdd', 'subtopic'::public.curated_course_node_type, 'Engagement and co-design', 'People are more likely to use and trust services they have helped shape.', 2),
  ('af18ca04-99ae-4d6c-9faf-b92f52d66a8c', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '8573d725-0012-4ab0-ae34-8aa22bac6f6c', 'concept'::public.curated_course_node_type, 'Advisory groups, tasting panels, patient/resident councils, student/community partners, and labor-management input', null, 0),
  ('47446901-a926-4dc9-99d0-bbf5131e8241', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '8573d725-0012-4ab0-ae34-8aa22bac6f6c', 'concept'::public.curated_course_node_type, 'Co-design methods, compensation, power sharing, consent, feedback loops, and expectation management', null, 1),
  ('207f3304-ea12-408d-8646-8b1f3f90e6ff', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '8573d725-0012-4ab0-ae34-8aa22bac6f6c', 'concept'::public.curated_course_node_type, 'Partnership mapping, community benefit, evaluation, and transparent reporting', null, 2),
  ('66e19841-9845-45c9-a5e4-1820e13fa789', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', null, 'topic'::public.curated_course_node_type, 'Foodservice Management Project and Professional Integration', 'The capstone integrates the course into a decision-ready proposal for a real or realistic food and nutrition service. Students demonstrate that recommendations are safe, nutritionally sound, financially credible, operationally feasible, equitable, sustainable, and measurable.', 14),
  ('e29b3b32-d0a6-4064-a0b9-46f6960e10db', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '66e19841-9845-45c9-a5e4-1820e13fa789', 'subtopic'::public.curated_course_node_type, 'Problem definition and evidence gathering', 'Students begin with a clearly bounded management problem, stakeholders, baseline, and decision criteria.', 0),
  ('6454c1b0-98d2-4424-b6de-ba9f9beca980', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'e29b3b32-d0a6-4064-a0b9-46f6960e10db', 'concept'::public.curated_course_node_type, 'Project charter, scope, sponsor, stakeholders, users, assumptions, constraints, risks, and ethics', null, 0),
  ('a34bf153-2891-4b9b-ab1d-3341b209305b', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'e29b3b32-d0a6-4064-a0b9-46f6960e10db', 'concept'::public.curated_course_node_type, 'Needs assessment, workflow observation, interviews, operational data, literature, standards, and benchmarking', null, 1),
  ('8fbb836e-8996-497b-a09d-f85a9f8705f8', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'e29b3b32-d0a6-4064-a0b9-46f6960e10db', 'concept'::public.curated_course_node_type, 'Baseline measures, root causes, equity considerations, and measurable aim statement', null, 2),
  ('eaecc8db-aba3-4054-96d1-99bbb0f0de80', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '66e19841-9845-45c9-a5e4-1820e13fa789', 'subtopic'::public.curated_course_node_type, 'Integrated operating and financial plan', 'The proposal must show how the service will work, not only why it is desirable.', 1),
  ('2f215855-761e-4b72-a585-f892880eb2e2', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'eaecc8db-aba3-4054-96d1-99bbb0f0de80', 'concept'::public.curated_course_node_type, 'Menu/service concept, demand forecast, process map, food-safety plan, suppliers, production/distribution model, and quality controls', null, 0),
