  ('54d35e76-0e23-4baf-a180-da25577400cf', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', 'eaecc8db-aba3-4054-96d1-99bbb0f0de80', 'concept'::public.curated_course_node_type, 'Sustainability, access, legal/regulatory review, emergency continuity, and change-management plan', null, 2),
  ('629bf8ee-4617-425a-9828-a2a6e23a04a0', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '66e19841-9845-45c9-a5e4-1820e13fa789', 'subtopic'::public.curated_course_node_type, 'Evaluation, presentation, and reflection', 'Students defend choices with evidence, acknowledge uncertainty, and specify how results will be evaluated.', 2),
  ('b5e6238e-ebd6-4526-9dda-063915527793', 'b6f2d8e4-3c17-4a09-9b25-1e0d7c5a6f38', '629bf8ee-4617-425a-9828-a2a6e23a04a0', 'concept'::public.curated_course_node_type, 'Process, outcome, balancing, financial, experience, workforce, equity, and sustainability measures', null, 0),
